// Package: LLamaIndex (or custom implementation following LlamaIndex patterns)
// Demonstrates indexing, retrieval, and grounded generation in a C# service.

using System.Text;

public sealed record Document(string Id, string Title, string Content);
public sealed record Node(string Id, string DocumentId, int ChunkIndex, string Text, ReadOnlyMemory<float> Vector);
public sealed record RetrievedNode(Node Node, float Score);

public interface IIndex
{
    Task AddDocumentsAsync(IEnumerable<Document> documents, CancellationToken ct = default);
    Task<IReadOnlyList<RetrievedNode>> RetrieveAsync(string query, int topK = 5, CancellationToken ct = default);
}

public sealed class LlamaIndexStyleRagService
{
    private readonly IIndex _index;
    private readonly IChatClient _chatClient;

    public LlamaIndexStyleRagService(IIndex index, IChatClient chatClient)
    {
        _index = index ?? throw new ArgumentNullException(nameof(index));
        _chatClient = chatClient ?? throw new ArgumentNullException(nameof(chatClient));
    }

    public async Task<string> QueryAsync(string question, int topK = 5, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(question);

        var retrievedNodes = await _index.RetrieveAsync(question, topK, ct);

        if (retrievedNodes.Count == 0)
        {
            return "I could not find any relevant information to answer your question.";
        }

        var context = new StringBuilder();
        foreach (var (node, score) in retrievedNodes)
        {
            context.AppendLine($"[Node {node.Id}] (score: {score:F2})");
            context.AppendLine(node.Text);
            context.AppendLine("---");
        }

        var prompt = $"""
Use the following context to answer the question. Cite nodes using [Node X].

Context:
{context}

Question:
{question}
""";

        var messages = new[]
        {
            new ChatMessage(ChatRole.System, "You are a helpful assistant that answers accurately using only the provided context."),
            new ChatMessage(ChatRole.User, prompt)
        };

        var response = await _chatClient.GetResponseAsync(messages, ct);
        return response.Messages.Last().Text ?? string.Empty;
    }
}

